def get_mo_description(mo_class):
    """Get description for an MO class"""
    return MO_DESCRIPTIONS.get(mo_class, "No description available.")

def get_mo_category(mo_class):
    """Get category for an MO class"""
    return MO_CATEGORIES.get(mo_class, "Other")

def get_param_description(param_name):
    """Get description for a parameter"""
    return PARAM_DESCRIPTIONS.get(param_name, "No description available.")

def get_Embedded_categorization(cat):
    return EMBEDDED_CATEGORIZATION.get(cat, {})

# Extract MO_TO_PARAMS from EMBEDDED_CATEGORIZATION
MO_TO_PARAMS = EMBEDDED_CATEGORIZATION.get('mo_to_params', {})

def get_mo_params(mo_class):
    """Get list of parameters for an MO class"""
    return MO_TO_PARAMS.get(mo_class, [])

if __name__ == "__main__":
    print(f"MO Descriptions loaded: {len(MO_DESCRIPTIONS)}")
    print(f"MO Categories loaded: {len(MO_CATEGORIES)}")
    print(f"Parameter Descriptions loaded: {len(PARAM_DESCRIPTIONS)}")
    print("\nSample MOs:")
    for mo in list(MO_DESCRIPTIONS.keys())[:5]:
        print(f"  - {mo}: {get_mo_category(mo)}")
    print("\nSample Parameters:")
    for param in list(PARAM_DESCRIPTIONS.keys())[:5]:
        print(f"  - {param}")
